//! K10 kernel-side trust service initialization and policy self-test.
use crate::{capability::{Capability,CapabilitySet,SubjectKind},serial,sha256,trust::{Approval,SignedManifest,SignatureVerifier,TrustKey,TrustLevel,TrustStore},update::{Slot,UpdateManager}};
struct SelfTestVerifier;impl SignatureVerifier for SelfTestVerifier{fn verify(&self,_:&[u8;32],message:&[u8;32],signature:&[u8;64])->bool{signature[..32]==message[..]}}
pub fn initialize(){let vector=sha256::digest(b"abc");let expected=[0xba,0x78,0x16,0xbf,0x8f,0x01,0xcf,0xea,0x41,0x41,0x40,0xde,0x5d,0xae,0x22,0x23,0xb0,0x03,0x61,0xa3,0x96,0x17,0x7a,0x9c,0xb4,0x10,0xff,0x61,0xf2,0x00,0x15,0xad];if vector!=expected{serial::println(format_args!("[TRUST] SHA-256 self-test failed"));return}let mut store=TrustStore::new();let id=sha256::digest(b"titanweave-platform-key");let key=TrustKey{id,public_key:[7;32],level:TrustLevel::Platform,enabled:true};if store.add_key(key).is_err(){return}let subject=sha256::digest(b"k10-self-test");let mut caps=CapabilitySet::empty();caps.insert(Capability::SystemUpdate);caps.insert(Capability::PackageInstall);let mut sig=[0u8;64];sig[..32].copy_from_slice(&subject);let manifest=SignedManifest{subject_hash:subject,signer_id:id,kind:SubjectKind::Update,capabilities:caps,version:10,minimum_system_version:10,signature:sig};let verified=store.verify(&manifest,10,0,&SelfTestVerifier).is_ok();let mut update=UpdateManager::new(9);let update_ok=update.stage(Slot::B,10).and_then(|_|update.mark_verified()).and_then(|_|update.activate().map(|_|())).and_then(|_|update.record_boot()).and_then(|_|update.confirm()).is_ok();let _=Approval::EMPTY;serial::println(format_args!("[TRUST] K10 trust={} update={} active={:?}",verified,update_ok,update.active));}
